(function () {
'use strict';
document.addEventListener('DOMContentLoaded', () => {
const tabLogin = document.getElementById('tabLogin');
const tabSignup = document.getElementById('tabSignup');
const formLogin = document.getElementById('formLogin');
const formSignup = document.getElementById('formSignup');
if (tabLogin && tabSignup) {
tabLogin.addEventListener('click', () => {
tabLogin.classList.add('active');
tabSignup.classList.remove('active');
formLogin.style.display = 'block';
formSignup.style.display = 'none';
});
tabSignup.addEventListener('click', () => {
tabSignup.classList.add('active');
tabLogin.classList.remove('active');
formLogin.style.display = 'none';
formSignup.style.display = 'block';
});
}
document.querySelectorAll('.btn-toggle-pw').forEach((btn) => {
btn.addEventListener('click', () => {
const input = btn.previousElementSibling;
if (input && input.type) {
input.type = input.type === 'password' ? 'text' : 'password';
}
});
});
document.querySelectorAll('[data-demo-login]').forEach((btn) => {
btn.addEventListener('click', (e) => {
e.preventDefault();
const role = btn.getAttribute('data-demo-login');
let email = 'athlete@pulseforge.io';
let pw = 'PulseAthlete123!';
if (role === 'admin') {
email = 'admin@pulseforge.io';
pw = 'PulseAdmin123!';
} else if (role === 'coach') {
email = 'coach@pulseforge.io';
pw = 'PulseCoach123!';
}
if (formLogin) {
formLogin.email.value = email;
formLogin.password.value = pw;
}
if (window.PulseForgeStore) {
const user = window.PulseForgeStore.switchDemoRole(role);
if (window.showToast) {
window.showToast(`Logged in as Demo ${role.toUpperCase()}: ${user.name}`, 'success');
}
const redirect = new URLSearchParams(window.location.search).get('redirect') || 'dashboard.html';
setTimeout(() => {
window.location.href = redirect;
}, 450);
}
});
});
if (formLogin) {
formLogin.addEventListener('submit', (e) => {
e.preventDefault();
const email = formLogin.email.value.trim();
const password = formLogin.password.value;
const submitBtn = formLogin.querySelector('button[type="submit"]');
if (submitBtn) {
submitBtn.disabled = true;
submitBtn.textContent = 'Verifying credentials...';
}
if (window.PulseForgeStore) {
const result = window.PulseForgeStore.login(email, password);
if (result.success) {
if (window.showToast) {
window.showToast(`Access granted: ${result.user.name}`, 'success');
}
const redirect = new URLSearchParams(window.location.search).get('redirect') || 'dashboard.html';
setTimeout(() => {
window.location.href = redirect;
}, 500);
} else {
if (window.showToast) {
window.showToast('Invalid credentials. Please try again.', 'error');
}
if (submitBtn) {
submitBtn.disabled = false;
submitBtn.textContent = 'Sign In to PulseForge';
}
}
}
});
}
if (formSignup) {
formSignup.addEventListener('submit', (e) => {
e.preventDefault();
const name = formSignup.name.value.trim();
const email = formSignup.email.value.trim();
const password = formSignup.password.value;
const role = formSignup.role ? formSignup.role.value : 'client';
if (!name || !email || !password) {
if (window.showToast) window.showToast('Please complete all required fields.', 'error');
return;
}
const submitBtn = formSignup.querySelector('button[type="submit"]');
if (submitBtn) {
submitBtn.disabled = true;
submitBtn.textContent = 'Creating account...';
}
if (window.PulseForgeStore) {
const result = window.PulseForgeStore.signup({ name, email, password, role });
if (result.success) {
if (window.showToast) {
window.showToast('Welcome to PulseForge! Redirecting to Dashboard...', 'success');
}
setTimeout(() => {
window.location.href = 'dashboard.html';
}, 600);
}
}
});
}
const forgotLink = document.getElementById('linkForgotPassword');
if (forgotLink) {
forgotLink.addEventListener('click', (e) => {
e.preventDefault();
const email = formLogin ? formLogin.email.value : '';
if (!email) {
if (window.showToast) window.showToast('Please enter your email above to receive password reset instructions.', 'info');
} else {
if (window.showToast) window.showToast(`Biometric authentication reset link dispatched to: ${email}`, 'success');
}
});
}
});
})();